    ref_links = state.env.get('ref_links', {})
    for key in ref_links:
        attrs = ref_links[key]
        text = '[' + attrs['label'] + ']: ' + attrs['url']
        title = attrs.get('title')
        if title:
            text += ' "' + title + '"'
        yield text

def block_text(self, token: Dict[str, Any], state: BlockState) -> str:
